// Normalize Microsoft Graph calendar events into the Jytte `calendar`
// widget payload.
//
// Input : raw Graph event objects from 'Fetch today events'. That node
//         has alwaysOutputData on, so a day with no meetings still
//         reaches the push - it arrives as a single {} item, dropped by
//         the `id` check. Without it, a free day would look identical
//         to a broken fetch.
// Output: exactly one item - the body POSTed to /widgets/calendar/state.

const cfg = $('Config').first().json;

const joinUrl = (m) => {
  // Teams join link lives in onlineMeeting.joinUrl, but older items only
  // carry it in the body HTML. Check both before giving up.
  if (m.onlineMeeting && m.onlineMeeting.joinUrl) return m.onlineMeeting.joinUrl;
  const body = (m.body && m.body.content) || '';
  const hit = body.match(/https:\/\/teams\.microsoft\.com\/l\/meetup-join\/[^"'\s<>]+/);
  return hit ? hit[0] : null;
};

const events = [];
for (const item of $input.all()) {
  const m = item.json || {};
  if (!m.id) continue;

  const attendees = Array.isArray(m.attendees) ? m.attendees : [];
  events.push({
    id: m.id,
    subject: m.subject || '(uden emne)',
    start: (m.start && m.start.dateTime) || null,
    end: (m.end && m.end.dateTime) || null,
    all_day: m.isAllDay === true,
    cancelled: m.isCancelled === true,
    organizer: (m.organizer && m.organizer.emailAddress && m.organizer.emailAddress.name) || '',
    location: (m.location && m.location.displayName) || '',
    online: m.isOnlineMeeting === true,
    join_url: joinUrl(m),
    web_link: m.webLink || null,
    // Names only. Addresses are not needed to render and would put a
    // list of colleagues' email addresses into a cached payload.
    attendees: attendees
      .map((a) => (a.emailAddress && a.emailAddress.name) || '')
      .filter(Boolean)
      .slice(0, 8),
    attendee_count: attendees.length,
    response: (m.responseStatus && m.responseStatus.response) || 'none',
  });
}

// Graph honours $orderby here, but sort anyway so the payload is
// ordered even if the query changes.
events.sort((a, b) => String(a.start || '').localeCompare(String(b.start || '')));

const timed = events.filter((e) => !e.all_day && !e.cancelled);
const first = timed.length ? timed[0] : null;

// Gaps between consecutive meetings, so the UI can show "2 t 15 m fri"
// without recomputing it per render.
const gaps = [];
for (let i = 0; i < timed.length - 1; i++) {
  const endA = Date.parse(timed[i].end || '');
  const startB = Date.parse(timed[i + 1].start || '');
  if (!isNaN(endA) && !isNaN(startB) && startB > endA) {
    gaps.push({ after: timed[i].id, minutes: Math.round((startB - endA) / 60000) });
  }
}

const summary =
  events.length === 0
    ? 'kalender: ingen moeder i dag'
    : 'kalender: ' + events.length + ' moede' + (events.length === 1 ? '' : 'r') +
      (first ? ', foerste ' + String(first.start).slice(11, 16) : '');

return [
  {
    json: {
      ready: true,
      source: 'n8n',
      summary: summary,
      fetched_at: new Date().toISOString(),
      window_days: Number(cfg.window_days) || 1,
      counts: {
        total: events.length,
        timed: timed.length,
        all_day: events.filter((e) => e.all_day).length,
        cancelled: events.filter((e) => e.cancelled).length,
        online: events.filter((e) => e.online).length,
      },
      gaps: gaps,
      events: events,
    },
  },
];
